guard.template:

                    #include "guard.h"


BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.dac_b.name}_open_guard (dac_ctrl_t *p_api_ctrl, dac_cfg_t const *const p_cfg)
{
    /* TODO: add your own security checks here */

    FSP_PARAMETER_NOT_USED(p_api_ctrl);
    FSP_PARAMETER_NOT_USED(p_cfg);

    return R_DAC_B_Open(&${module.driver.dac_b.name}_ctrl, &${module.driver.dac_b.name}_cfg);
}

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.dac_b.name}_write_guard (dac_ctrl_t *p_api_ctrl, uint16_t value)
{
    /* TODO: add your own security checks here */

    FSP_PARAMETER_NOT_USED(p_api_ctrl);

    return R_DAC_B_Write(&${module.driver.dac_b.name}_ctrl, value);
}

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.dac_b.name}_start_guard (dac_ctrl_t *p_api_ctrl)
{
    /* TODO: add your own security checks here */

    FSP_PARAMETER_NOT_USED(p_api_ctrl);

    return R_DAC_B_Start(&${module.driver.dac_b.name}_ctrl);
}

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.dac_b.name}_stop_guard (dac_ctrl_t *p_api_ctrl)
{
    /* TODO: add your own security checks here */

    FSP_PARAMETER_NOT_USED(p_api_ctrl);

    return R_DAC_B_Stop(&${module.driver.dac_b.name}_ctrl);
}

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.dac_b.name}_close_guard (dac_ctrl_t *p_api_ctrl)
{
    /* TODO: add your own security checks here */

    FSP_PARAMETER_NOT_USED(p_api_ctrl);

    return R_DAC_B_Close(&${module.driver.dac_b.name}_ctrl);
}

nsc.header:
#define FSP_GUARD_${module.driver.dac_b.name}_R_DAC_B_Open() ${module.driver.dac_b.name}_open_guard(FSP_SECURE_ARGUMENT, FSP_SECURE_ARGUMENT)

#define FSP_GUARD_${module.driver.dac_b.name}_R_DAC_B_Write(value) ${module.driver.dac_b.name}_write_guard(FSP_SECURE_ARGUMENT, value)

#define FSP_GUARD_${module.driver.dac_b.name}_R_DAC_B_Start() ${module.driver.dac_b.name}_start_guard(FSP_SECURE_ARGUMENT)

#define FSP_GUARD_${module.driver.dac_b.name}_R_DAC_B_Stop() ${module.driver.dac_b.name}_stop_guard(FSP_SECURE_ARGUMENT)

#define FSP_GUARD_${module.driver.dac_b.name}_R_DAC_B_Close() ${module.driver.dac_b.name}_close_guard(FSP_SECURE_ARGUMENT)



BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.dac_b.name}_open_guard(dac_ctrl_t *p_api_ctrl, dac_cfg_t const *const p_cfg);

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.dac_b.name}_write_guard(dac_ctrl_t *p_api_ctrl, uint16_t value);

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.dac_b.name}_start_guard(dac_ctrl_t *p_api_ctrl);

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.dac_b.name}_stop_guard(dac_ctrl_t *p_api_ctrl);

BSP_CMSE_NONSECURE_ENTRY fsp_err_t ${module.driver.dac_b.name}_close_guard(dac_ctrl_t *p_api_ctrl);


extern const dac_instance_t ${module.driver.dac_b.name};

nsc.declarations:

static const dac_api_t ${module.driver.dac_b.name}_nsc_api =
{
    .open = ${module.driver.dac_b.name}_open_guard,
    .write = ${module.driver.dac_b.name}_write_guard,
    .start = ${module.driver.dac_b.name}_start_guard,
    .stop = ${module.driver.dac_b.name}_stop_guard,
    .close = ${module.driver.dac_b.name}_close_guard,
};
const dac_instance_t ${module.driver.dac_b.name} =
{
    .p_api = &${module.driver.dac_b.name}_nsc_api,
    .p_ctrl = FSP_SECURE_ARGUMENT,
    .p_cfg = FSP_SECURE_ARGUMENT,
};
